// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Dados juntados pelo Merge (clientes do Webhook + investimentos do CSV)
const dados = $input.first().json;

const clientes = dados.body?.clientes ?? $('Webhook').first().json.body.clientes;
const investimentos = dados.investimentos ?? $('Code in JavaScript').first().json.investimentos;

// Sorteia uma mensagem da lista
const pick = (lista) => lista[Math.floor(Math.random() * lista.length)];

// "R$ 12.500,00" -> 12500
const paraNumero = (texto) =>
  Number(String(texto).replace(/\./g, "").replace(/[^\d,]/g, "").replace(",", ".")) || 0;

const foco = {
  Conservador: "renda fixa e segurança",
  Moderado: "um mix equilibrado entre renda fixa e variável",
  Arrojado: "ações e maior potencial de retorno",
};

const resultados = clientes.map((c) => {
  const saldoNum = paraNumero(c.saldo);

  // Opções do perfil que o saldo do cliente permite contratar
  const possiveis = investimentos
    .filter((i) => i.perfil === c.perfil && i.minimo <= saldoNum)
    .sort((a, b) => b.minimo - a.minimo);

  const escolhido = possiveis[0] ?? null;

  const motivo = escolhido
    ? `Perfil ${c.perfil} com saldo de ${c.saldo}: ${escolhido.produto} exige mínimo de R$ ${escolhido.minimo} e é a opção mais robusta que cabe no saldo.`
    : `Perfil ${c.perfil} com saldo de ${c.saldo}: nenhuma opção atinge o mínimo exigido.`;

  const produto = escolhido
    ? `${escolhido.produto} (${escolhido.rentabilidade})`
    : "nenhuma opção disponível no momento";

  const mensagens = [
    `Olá, ${c.nome}! Pelo seu perfil ${c.perfil}, o foco é ${foco[c.perfil] ?? "diversificação"}. Com seu saldo de ${c.saldo}, recomendamos: ${produto}.`,
    `Oi, ${c.nome}! Para quem tem perfil ${c.perfil}, a prioridade é ${foco[c.perfil] ?? "diversificação"}. Sua melhor opção hoje é ${produto}.`,
    `${c.nome}, preparamos uma sugestão para você: ${produto}. Ela combina com seu perfil ${c.perfil} e com o saldo de ${c.saldo}.`,
  ];

  return {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados,
  },
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao ?? null,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida,
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva",
        ],
      },
    },
  };
});

return out;

