// Dados originais de cada cliente (email_to, nome, perfil, recomendacao, motivo...)
const originais = $('Code in JavaScript2').all();

// Para testar, coloque SEU e-mail aqui. Deixe "" para usar o e-mail de cada cliente.
const EMAIL_TESTE = "";

function lerJson(texto) {
  const limpo = String(texto || "").replace(/```json|```/gi, "").trim();
  const ini = limpo.indexOf("{");
  const fim = limpo.lastIndexOf("}");
  if (ini === -1 || fim === -1) return null;
  try {
    return JSON.parse(limpo.slice(ini, fim + 1));
  } catch (e) {
    return null;
  }
}

const escapeHtml = (s) =>
  String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const emailValido = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

return $input.all().map((item, i) => {
  const j = originais[i]?.json ?? {};

  // Texto que a IA devolveu
  const texto = item.json.output?.[0]?.content?.[0]?.text ?? "";
  const resposta = lerJson(texto) ?? {};

  const to = EMAIL_TESTE || String(j.email_to || "").trim();

  const subject = String(
    resposta.subject || `Sugestão de investimento para ${j.nome ?? "você"}`
  ).trim();

  const text_body = String(resposta.text_body || j.mensagem_base || "").trim();

  const html_body = String(
    resposta.html_body ||
      `<p>${escapeHtml(text_body).replace(/\n+/g, "</p><p>")}</p>`
  ).trim();

  return {
    json: {
      ok: emailValido(to),
      to,
      subject,
      text_body,
      html_body,

      // (opcional) campos úteis pra debug
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo,
      },
    },
  };
});
